window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-1cad973604da2718"]={"versions": [{"id": "FIG-1cad973604da2718", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Use-Case-Diagramm (Anwendungsfalldiagramm) im Kontext der AUTOSAR-Timing-Analyse (AUTOSAR_TR_TimingAnalysis). Das Diagramm definiert den Systemrahmen „End-to-End Timing Analysis for Distributed“ und ordnet rollenbasierten Ingenieursakteuren konkrete E2E-Timing-Anwendungsfälle über Systemgrenzen hinweg zu. Ein Notizfeld vermerkt übergeordnet: „This diagram contains all relevant end-to-end uses-cases“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine Systemgrenze (Boundary-Box) namens <code>End-to-End Timing Analysis for Distributed</code> mit vier Akteuren und fünf Anwendungsfällen (Use-Cases mit Stereotyp <code>«e2e»</code>):</p>\n<p class=\"fig-p\"><strong>Akteure (Rollen):</strong></p>\n<ul class=\"fig-list\"><li><code>:Function Engineer</code> (links oben)\n</li><li><code>:Test Engineer</code> (links unten)\n</li><li><code>:ECU Integrator</code> (rechts oben)\n</li><li><code>:NW Data Engineer</code> (rechts mittig)\n</li></ul>\n<p class=\"fig-p\"><strong>Use-Cases (grüne Ellipsen, stereotypisiert mit <code>«e2e»</code>):</strong></p>\n<ul class=\"fig-list\"><li><code>Derive per-hop time budgets from End-to-End timing requirements</code>\n</li><li><code>Deriving timing requirements from the timing assessment of an existing implementation</code>\n</li><li><code>Specify Timing Requirements for Signals/Parameters</code>\n</li><li><code>Assert timing requirements against guarantees</code>\n</li><li><code>Trace-based timing assessment of a distributed implementation</code>\n</li></ul>\n<p class=\"fig-p\"><strong>Schnittstellen / Assoziationen (Verbindungslinien):</strong></p>\n<ul class=\"fig-list\"><li><code>:Function Engineer</code> ist assoziiert mit:\n<ul class=\"fig-list\"><li><code>Derive per-hop time budgets from End-to-End timing requirements</code>\n</li><li><code>Deriving timing requirements from the timing assessment of an existing implementation</code>\n</li></ul>\n</li><li><code>:Test Engineer</code> ist assoziiert mit:\n<ul class=\"fig-list\"><li><code>Deriving timing requirements from the timing assessment of an existing implementation</code> (Linie kreuzt die Verbindung von <code>:NW Data Engineer</code> mit Brückensymbol)\n</li><li><code>Assert timing requirements against guarantees</code>\n</li><li><code>Trace-based timing assessment of a distributed implementation</code>\n</li></ul>\n</li><li><code>:ECU Integrator</code> ist assoziiert mit:\n<ul class=\"fig-list\"><li><code>Derive per-hop time budgets from End-to-End timing requirements</code>\n</li></ul>\n</li><li><code>:NW Data Engineer</code> ist assoziiert mit:\n<ul class=\"fig-list\"><li><code>Derive per-hop time budgets from End-to-End timing requirements</code>\n</li><li><code>Specify Timing Requirements for Signals/Parameters</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Zuordnung von Verantwortlichkeiten und Workflows im End-to-End-Timing-Entwicklungsprozess:</p>\n<ul class=\"fig-list\"><li><strong>Anforderungs- und Budgetdefinition:</strong> Der <code>:Function Engineer</code> initiiert E2E-Timing-Vorgaben und leitet gemeinsam mit dem <code>:ECU Integrator</code> und dem <code>:NW Data Engineer</code> Hop-basierte Zeitbudgets (<code>Derive per-hop time budgets from End-to-End timing requirements</code>) ab.\n</li><li><strong>Parametrisierung:</strong> Der <code>:NW Data Engineer</code> spezifiziert Timing-Anforderungen auf Signal- und Parameterebene (<code>Specify Timing Requirements for Signals/Parameters</code>).\n</li><li><strong>Verifikation und bestehende Systeme:</strong> Aus bestehenden Implementierungen leiten <code>:Function Engineer</code> und <code>:Test Engineer</code> Timing-Anforderungen iterativ ab (<code>Deriving timing requirements from the timing assessment of an existing implementation</code>).\n</li><li><strong>Absicherung und Trace-Analyse:</strong> Der <code>:Test Engineer</code> prüft Timing-Anforderungen gegen Garantien (<code>Assert timing requirements against guarantees</code>) und führt trace-basierte Timing-Bewertungen verteilter Implementierungen durch (<code>Trace-based timing assessment of a distributed implementation</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als konzeptioneller Leitfaden (Technical Report) für AUTOSAR-Entwickler und Tool-Hersteller zur methodischen Verteilung von Timing-Aufgaben auf disziplinspezifische Rollen. Es verdeutlicht die notwendige Artefakt- und Modellübergabe zwischen Funktionsentwicklung, Netzwerkdesign, ECU-Integration und Test bei verteilten AUTOSAR-Systemen. Die Benennung und Trennung der Anwendungsfälle erfordert eine konsistente Abbildung in Timing-Authoring-Tools und Modellierungs-Workflows (z. B. AUTOSAR Timing Extensions).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-32fa053cd91f8e20", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Use-Case-Diagramm (Anwendungsfalldiagramm) im Kontext der AUTOSAR-Timing-Analyse (AUTOSAR_TR_TimingAnalysis). Das Diagramm definiert den Systemrahmen „End-to-End Timing Analysis for Distributed“ und ordnet rollenbasierten Ingenieursakteuren konkrete E2E-Timing-Anwendungsfälle über Systemgrenzen hinweg zu. Ein Notizfeld vermerkt übergeordnet: „This diagram contains all relevant end-to-end uses-cases“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine Systemgrenze (Boundary-Box) namens <code>End-to-End Timing Analysis for Distributed</code> mit vier Akteuren und fünf Anwendungsfällen (Use-Cases mit Stereotyp <code>«e2e»</code>):</p>\n<p class=\"fig-p\"><strong>Akteure (Rollen):</strong></p>\n<ul class=\"fig-list\"><li><code>:Function Engineer</code> (links oben)\n</li><li><code>:Test Engineer</code> (links unten)\n</li><li><code>:ECU Integrator</code> (rechts oben)\n</li><li><code>:NW Data Engineer</code> (rechts mittig)\n</li></ul>\n<p class=\"fig-p\"><strong>Use-Cases (grüne Ellipsen, stereotypisiert mit <code>«e2e»</code>):</strong></p>\n<ul class=\"fig-list\"><li><code>Derive per-hop time budgets from End-to-End timing requirements</code>\n</li><li><code>Deriving timing requirements from the timing assessment of an existing implementation</code>\n</li><li><code>Specify Timing Requirements for functional interfaces based on Signals/Parameters</code>\n</li><li><code>Assert timing requirements against guarantees</code>\n</li><li><code>Trace-based timing assessment of a distributed implementation</code>\n</li></ul>\n<p class=\"fig-p\"><strong>Schnittstellen / Assoziationen (Verbindungslinien):</strong></p>\n<ul class=\"fig-list\"><li><code>:Function Engineer</code> ist assoziiert mit:\n<ul class=\"fig-list\"><li><code>Derive per-hop time budgets from End-to-End timing requirements</code>\n</li><li><code>Deriving timing requirements from the timing assessment of an existing implementation</code>\n</li></ul>\n</li><li><code>:Test Engineer</code> ist assoziiert mit:\n<ul class=\"fig-list\"><li><code>Deriving timing requirements from the timing assessment of an existing implementation</code> (Linie kreuzt die Verbindung von <code>:NW Data Engineer</code> mit Brückensymbol)\n</li><li><code>Assert timing requirements against guarantees</code>\n</li><li><code>Trace-based timing assessment of a distributed implementation</code>\n</li></ul>\n</li><li><code>:ECU Integrator</code> ist assoziiert mit:\n<ul class=\"fig-list\"><li><code>Derive per-hop time budgets from End-to-End timing requirements</code>\n</li></ul>\n</li><li><code>:NW Data Engineer</code> ist assoziiert mit:\n<ul class=\"fig-list\"><li><code>Derive per-hop time budgets from End-to-End timing requirements</code>\n</li><li><code>Specify Timing Requirements for functional interfaces based on Signals/Parameters</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Zuordnung von Verantwortlichkeiten und Workflows im End-to-End-Timing-Entwicklungsprozess:</p>\n<ul class=\"fig-list\"><li><strong>Anforderungs- und Budgetdefinition:</strong> Der <code>:Function Engineer</code> initiiert E2E-Timing-Vorgaben und leitet gemeinsam mit dem <code>:ECU Integrator</code> und dem <code>:NW Data Engineer</code> Hop-basierte Zeitbudgets (<code>Derive per-hop time budgets from End-to-End timing requirements</code>) ab.\n</li><li><strong>Parametrisierung:</strong> Der <code>:NW Data Engineer</code> spezifiziert Timing-Anforderungen auf Signal- und Parameterebene (<code>Specify Timing Requirements for Signals/Parameters</code>).\n</li><li><strong>Verifikation und bestehende Systeme:</strong> Aus bestehenden Implementierungen leiten <code>:Function Engineer</code> und <code>:Test Engineer</code> Timing-Anforderungen iterativ ab (<code>Deriving timing requirements from the timing assessment of an existing implementation</code>).\n</li><li><strong>Absicherung und Trace-Analyse:</strong> Der <code>:Test Engineer</code> prüft Timing-Anforderungen gegen Garantien (<code>Assert timing requirements against guarantees</code>) und führt trace-basierte Timing-Bewertungen verteilter Implementierungen durch (<code>Trace-based timing assessment of a distributed implementation</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als konzeptioneller Leitfaden (Technical Report) für AUTOSAR-Entwickler und Tool-Hersteller zur methodischen Verteilung von Timing-Aufgaben auf disziplinspezifische Rollen. Es verdeutlicht die notwendige Artefakt- und Modellübergabe zwischen Funktionsentwicklung, Netzwerkdesign, ECU-Integration und Test bei verteilten AUTOSAR-Systemen. Die Benennung und Trennung der Anwendungsfälle erfordert eine konsistente Abbildung in Timing-Authoring-Tools und Modellierungs-Workflows (z. B. AUTOSAR Timing Extensions).</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7733ba38845e0dd2", "releases": ["R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Use-Case-Diagramm (Anwendungsfalldiagramm) im Kontext der AUTOSAR-Timing-Analyse (AUTOSAR_TR_TimingAnalysis). Das Diagramm definiert den Systemrahmen „End-to-End Timing Analysis for Distributed“ und ordnet rollenbasierten Ingenieursakteuren konkrete E2E-Timing-Anwendungsfälle über Systemgrenzen hinweg zu. Ein Notizfeld vermerkt übergeordnet: „This diagram contains all relevant end-to-end uses-cases“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine Systemgrenze (Boundary-Box) namens <code>End-to-End Timing Analysis for Distributed</code> mit vier Akteuren und sechs Anwendungsfällen (Use-Cases mit Stereotyp <code>«e2e»</code>):</p>\n<p class=\"fig-p\"><strong>Akteure (Rollen):</strong></p>\n<ul class=\"fig-list\"><li><code>:Function Engineer</code> (links oben)\n</li><li><code>:Test Engineer</code> (links unten)\n</li><li><code>:ECU Integrator</code> (rechts oben)\n</li><li><code>:NW Data Engineer</code> (rechts mittig)\n</li></ul>\n<p class=\"fig-p\"><strong>Use-Cases (grüne Ellipsen, stereotypisiert mit <code>«e2e»</code>):</strong></p>\n<ul class=\"fig-list\"><li><code>Derive per-hop time budgets from End-to-End timing requirements</code>\n</li><li><code>Introduction of Service-Oriented Communication</code>\n</li><li><code>Specify Timing Requirements for functional interfaces based on Signals/Parameters</code>\n</li><li><code>Deriving timing requirements from the timing assessment of an existing implementation</code>\n</li><li><code>Assert timing requirements against guarantees</code>\n</li><li><code>Trace-based timing assessment of a distributed implementation</code>\n</li></ul>\n<p class=\"fig-p\"><strong>Schnittstellen / Assoziationen (Verbindungslinien):</strong></p>\n<ul class=\"fig-list\"><li><code>:Function Engineer</code> ist assoziiert mit:\n<ul class=\"fig-list\"><li><code>Derive per-hop time budgets from End-to-End timing requirements</code>\n</li><li><code>Introduction of Service-Oriented Communication</code>\n</li><li><code>Specify Timing Requirements for functional interfaces based on Signals/Parameters</code>\n</li></ul>\n</li><li><code>:Test Engineer</code> ist assoziiert mit:\n<ul class=\"fig-list\"><li><code>Deriving timing requirements from the timing assessment of an existing implementation</code>\n</li><li><code>Assert timing requirements against guarantees</code>\n</li><li><code>Trace-based timing assessment of a distributed implementation</code>\n</li></ul>\n</li><li><code>:ECU Integrator</code> ist assoziiert mit:\n<ul class=\"fig-list\"><li><code>Derive per-hop time budgets from End-to-End timing requirements</code>\n</li></ul>\n</li><li><code>:NW Data Engineer</code> ist assoziiert mit:\n<ul class=\"fig-list\"><li><code>Derive per-hop time budgets from End-to-End timing requirements</code>\n</li><li><code>Specify Timing Requirements for functional interfaces based on Signals/Parameters</code>\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Hinweis zur Leitungsführung: Die Assoziationslinie zwischen <code>:Function Engineer</code> und <code>Introduction of Service-Oriented Communication</code> wird von der Assoziationslinie zwischen dem oberen Use-Case und <code>:NW Data Engineer</code> per Brückensymbol überquert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Zuordnung von Verantwortlichkeiten und Workflows im End-to-End-Timing-Entwicklungsprozess:</p>\n<ul class=\"fig-list\"><li><strong>Anforderungs- und Budgetdefinition:</strong> Der <code>:Function Engineer</code> definiert E2E-Timing-Vorgaben und leitet gemeinsam mit dem <code>:ECU Integrator</code> und dem <code>:NW Data Engineer</code> Hop-basierte Zeitbudgets (<code>Derive per-hop time budgets from End-to-End timing requirements</code>) ab.\n</li><li><strong>Serviceorientierte Kommunikation:</strong> Der <code>:Function Engineer</code> bindet serviceorientierte Kommunikationsmuster in das Timing-Design ein (<code>Introduction of Service-Oriented Communication</code>).\n</li><li><strong>Schnittstellenspezifikation:</strong> <code>:Function Engineer</code> und <code>:NW Data Engineer</code> spezifizieren Timing-Anforderungen für funktionale Schnittstellen auf Basis von Signalen und Parametern (<code>Specify Timing Requirements for functional interfaces based on Signals/Parameters</code>).\n</li><li><strong>Verifikation und bestehende Systeme:</strong> Der <code>:Test Engineer</code> leitet Timing-Anforderungen aus der Bewertung bestehender Implementierungen ab (<code>Deriving timing requirements from the timing assessment of an existing implementation</code>).\n</li><li><strong>Absicherung und Trace-Analyse:</strong> Der <code>:Test Engineer</code> verifiziert Timing-Anforderungen gegenüber Garantien (<code>Assert timing requirements against guarantees</code>) und führt trace-basierte Timing-Analysen an verteilten Systemen durch (<code>Trace-based timing assessment of a distributed implementation</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Erweiterung des Anwendungsbereichs um serviceorientierte Architekturen (Adaptive Platform / SOME/IP). Entwickler und Methodik-Verantwortliche müssen bei der E2E-Timing-Modellierung nicht mehr ausschließlich signalbasierte Schnittstellen berücksichtigen, sondern die Einführung von Service-Oriented Communication (z. B. Events, Methods, Fields) und deren spezifische Latenzen und Event-Ketten in den Standard-Timing-Workflow integrieren.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-1cad973604da2718", "to": "FIG-32fa053cd91f8e20", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Textlicher Bezeichner des Use-Case: <code>Specify Timing Requirements for Signals/Parameters</code> angepasst zu <code>Specify Timing Requirements for functional interfaces based on Signals/Parameters</code>.\n</li><li>Visuelles Redesign der Akteur-Symbole von blau ausgefüllten Köpfen zu einfachen, nicht ausgefüllten Strichfiguren.\n</li></ul>"}, {"from": "FIG-32fa053cd91f8e20", "to": "FIG-7733ba38845e0dd2", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Neuer Use-Case: <code>«e2e» Introduction of Service-Oriented Communication</code> innerhalb der Systemgrenze eingefügt.\n</li><li>Assoziation ergänzt: Verbindung zwischen Akteur <code>:Function Engineer</code> und dem neuen Use-Case <code>Introduction of Service-Oriented Communication</code>.\n</li><li>Layout neu arrangiert: <code>Deriving timing requirements from the timing assessment of an existing implementation</code> nach unten verschoben, Kreuzung der Assoziationslinien zwischen <code>:Test Engineer</code> / <code>Deriving timing requirements...</code> und <code>:Function Engineer</code> / <code>Specify Timing Requirements...</code> entflochten.\n</li><li>Neue Linienkreuzung mit Brückensymbol eingeführt zwischen der Assoziation <code>:ECU Integrator</code> zu <code>:Function Engineer</code>/<code>Trace-based timing assessment...</code> und der Assoziation <code>:Function Engineer</code> zu <code>Introduction of Service-Oriented Communication</code>.\n</li></ul>"}]};
